#!/bin/sh
[ "$3" = --run ] || { echo "unexpected lake call: $*" >&2; exit 1; }
[ -f "$4" ] || { echo "missing exporter $4" >&2; exit 1; }
name=$(basename "$4" .lean)
cp "$5" "$FAKE_CAPTURE/$name.json"
cat "$FAKE_OUTPUTS/$name.json"
